.teammateRow {
  /* AI 팀원 입장 모션: 새 팀원이 생기면 자연스럽게 들어옵니다 (docs/110 U1) */
  animation: messageIn var(--mc-dur-base) var(--mc-ease-out) both;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 24px;
  align-items: center;
  gap: 2px;
  border-radius: var(--mc-radius-md);
}

.teammateRow:has(.teammateRemove:disabled) {
  opacity: 0.72;
 background-color: var(--mc-surface-sunken); color: var(--mc-text-faint); border-color: var(--mc-border-subtle); cursor: not-allowed; }

.teammateItem {
  /* 크루 한 줄 = 신분증: 아바타 / 이름 / 상태. 어느 칸도 다른 칸의 폭을
     빼앗지 못하게 고정한다(예전엔 이름 칸이 0px 까지 짓눌려 세로로 찢어졌다). */
  min-width: 0;
  width: 100%;
  min-height: 40px;
  display: grid;
  /* 이름은 제 폭을 갖고(짧음), 긴 보조 설명 칸이 남은 폭 안에서 말줄임된다.
     예전( … minmax(0,1fr) auto )에는 보조 칸이 auto라 원문 폭을 고집해 이름을 짓눌렀다. */
  grid-template-columns: 24px minmax(auto, max-content) minmax(0, 1fr);
  align-items: center;
  column-gap: 8px;
  row-gap: 1px;
  padding: 4px 8px;
  border-radius: var(--mc-radius-md);
  color: var(--mc-text-muted);
  text-align: left;
  transition:
    background var(--mc-dur-fast) var(--mc-ease-out),
    color var(--mc-dur-fast) var(--mc-ease-out),
    transform var(--mc-dur-fast) var(--mc-ease-out);
}

/* 아주 긴 이름이 보조 설명을 완전히 밀어내지 않게 이름 폭을 한 번 더 가둔다. */
.teammateItem strong { max-width: 128px; }

.teammateItem:hover {
  background: var(--mc-surface-muted);
  color: var(--mc-text-strong);
  transform: translateX(1px);
}

.teammateRow[data-active="true"] .teammateItem {
  background: color-mix(in srgb, var(--mc-primary) 11%, var(--mc-surface-muted));
  box-shadow: inset 2px 0 0 color-mix(in srgb, var(--mc-primary) 74%, transparent);
  color: var(--mc-text-strong);
}

.teammateItem > span,
.workerStatusPanel button > span {
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--mc-radius-md);
  background: var(--mc-primary-soft);
  color: var(--mc-primary);
  font-size: 11px;
  font-weight: var(--mc-weight-bold);
}

.teammateRow[data-running="true"] .teammateItem > span,
.workerStatusPanel button > span[data-running="true"] {
  background: var(--mc-safe-soft);
  color: var(--mc-safe);
  box-shadow: 0 0 0 3px var(--mc-safe-bg);
  /* "일하는 중" 라이브 신호 — 아바타가 부드럽게 숨쉬듯 점멸 (메타버스 오피스 v0) */
  animation: thinkingDotFade 1600ms ease-in-out infinite;
}

/* 진행 중 활동 라벨 — 펄스 점 + 강조색으로 "지금 무엇을 하는지" 실시간 표시 */
.teammateItem small[data-live-activity="true"] {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  color: var(--mc-safe);
}

.teammateItem small[data-live-activity="true"]::before {
  content: "";
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: var(--mc-safe);
  flex: 0 0 5px;
  animation: thinkingDotFade 1100ms ease-in-out infinite;
}

.teammateItem strong {
  grid-column: 2;
  min-width: 0;
  overflow: hidden;
  color: inherit;
  font-size: 12px;
  font-weight: var(--mc-weight-semibold);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 상태줄에 줄바꿈 금지가 없어서 좁은 칸에서 글자가 세로로 쌓였다.
   한 줄 + 말줄임으로 고정한다. */
.teammateItem small {
  /* 보조 설명은 한 줄로 자른다 — 칸이 좁아지면 한국어가 글자 단위로 세로로 꺾여
     아래 행들 위로 흘러내렸다. */
  overflow: hidden;
  min-width: 0;
  color: var(--mc-text-subtle);
  font-size: 12px;
  font-weight: var(--mc-weight-semibold);
  text-overflow: ellipsis;
  white-space: nowrap;
}

