.resizeHandleLeft,
.resizeHandleRight {
  position: absolute;
  z-index: 10;
  top: 0;
  width: 8px;
  height: 100%;
  cursor: col-resize;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.resizeHandleLeft {
  /* .sidebar overflow 에 4px 잘려 히트영역 절반만 동작하던 문제 (2026-07-25) */
  right: 0;
}

.resizeHandleRight {
  /* appFrame 직계 기준: 진행 패널 왼쪽 모서리에 10px 히트영역으로 걸침.
     (statusPanel 안 left:-4px 시절엔 overflow에 4px로 잘리던 문제) */
  right: max(0px, calc(var(--status-width) - 5px));
  left: auto;
  width: 10px;
}

.appFrame[data-status="closed"] .resizeHandleRight {
  display: none;
}

.resizeHandleLeft::after,
.resizeHandleRight::after {
  content: "";
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 4px;
  width: 2px;
  border-radius: 999px;
  background: transparent;
  /* 초점 링(box-shadow)은 즉시 보여야 해서 배경만 전환한다 (Hallmark 15) */
  transition: background var(--mc-dur-fast) var(--mc-ease-out);
}

.resizeHandleLeft:hover::after,
.resizeHandleLeft:focus-visible::after,
.resizeHandleRight:hover::after,
.resizeHandleRight:focus-visible::after,
.appFrame[data-resizing="left"] .resizeHandleLeft::after,
.appFrame[data-resizing="right"] .resizeHandleRight::after {
  background: color-mix(in srgb, var(--mc-primary) 58%, var(--mc-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--mc-primary) 12%, transparent);
}

/* 업무창(워크스페이스 드로어) 왼쪽 가장자리 폭 조절 핸들.
   패널이 overflow:hidden 이라 히트존을 패널 안쪽(left:0)에 둡니다. */
.resizeHandleDrawer {
  position: absolute;
  z-index: 30;
  top: 0;
  left: 0;
  width: 8px;
  height: 100%;
  cursor: col-resize;
  border: 0;
  border-radius: 0;
  padding: 0;
  background: transparent;
}

.resizeHandleDrawer::after {
  content: "";
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 2px;
  width: 2px;
  border-radius: 999px;
  background: transparent;
  /* 초점 링(box-shadow)은 즉시 보여야 해서 배경만 전환한다 (Hallmark 15) */
  transition: background var(--mc-dur-fast) var(--mc-ease-out);
}

.resizeHandleDrawer:hover::after,
.resizeHandleDrawer:focus-visible::after,
.appFrame[data-resizing="drawer"] .resizeHandleDrawer::after {
  background: color-mix(in srgb, var(--mc-primary) 58%, var(--mc-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--mc-primary) 12%, transparent);
}

@media (max-width: 760px) {
  /* 모바일 오버레이 모드에서는 폭 조절이 의미 없어 숨깁니다. */
  .resizeHandleDrawer {
    display: none;
  }
}

