  gap: 6px;
  align-items: start;
  padding: 8px;
  border: 1px solid var(--mc-border-subtle);
  border-radius: var(--mc-radius-md);
  background: color-mix(in srgb, var(--mc-surface-elevated) 58%, transparent);
}

.connectionHandoffRail li::after {
  content: "";
  position: absolute;
  right: -7px;
  top: 17px;
  width: 8px;
  height: 1px;
  background: color-mix(in srgb, var(--mc-border) 74%, transparent);
}

.connectionHandoffRail li:last-child::after {
  display: none;
}

.connectionHandoffRail i {
  width: 9px;
  height: 9px;
  margin-top: 4px;
  border-radius: 999px;
  background: var(--mc-text-muted);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--mc-text-muted) 9%, transparent);
}

.connectionHandoffRail li[data-state="done"] i,
.connectionHandoffRail li[data-state="ready"] i {
  background: var(--mc-safe);
  box-shadow: 0 0 0 4px var(--mc-safe-soft);
}

.connectionHandoffRail li[data-state="active"] {
  border-color: color-mix(in srgb, var(--mc-primary) 32%, var(--mc-border-subtle));
  background: color-mix(in srgb, var(--mc-primary-soft) 30%, var(--mc-surface));
}

.connectionHandoffRail li[data-state="active"] i {
  background: var(--mc-primary);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--mc-primary) 13%, transparent);
  animation: handoffPulse 1.35s ease-in-out infinite;
}

.connectionHandoffRail li[data-state="issue"] {
  border-color: color-mix(in srgb, var(--mc-warning) 34%, var(--mc-border-subtle));
  background: color-mix(in srgb, var(--mc-warning-bg) 48%, var(--mc-surface));
}

.connectionHandoffRail li[data-state="issue"] i {
  background: var(--mc-warning);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--mc-warning) 16%, transparent);
}

.connectionHandoffRail strong,
.connectionHandoffRail small {
  min-width: 0;
  overflow: hidden;
  display: block;
  text-overflow: ellipsis;
}

.connectionHandoffRail strong {
  color: var(--mc-text-strong);
  font-size: 11px;
  font-weight: var(--mc-weight-bold);
  white-space: nowrap;
}

.connectionHandoffRail small {
  color: var(--mc-text-muted);
  font-size: 12px;
  line-height: 1.42;
}

@keyframes handoffPulse {
  0%,
  100% {
    transform: scale(0.92);
    opacity: 0.8;
  }

  50% {
    transform: scale(1.12);
    opacity: 1;
  }
}

