}

.messageWorkerCreateAfterPath span {
  color: var(--mc-text-subtle);
  font-size: 12px;
  font-weight: var(--mc-weight-bold);
}

.messageWorkerCreateAfterPath strong {
  color: var(--mc-text-strong);
  font-size: 12px;
  font-weight: var(--mc-weight-bold);
}

.messageActions[data-message-action-surface="mail_assistant_workqueue_handoff"] button {
  width: 100%;
  min-width: 0;
}

.messageActions[data-message-action-surface="mail_assistant_workqueue_handoff"] button:first-of-type {
