  background: var(--mc-primary);
  color: var(--mc-text-inverse);
}

.messageActions[data-message-action-surface="worker_created_first_work_handoff"] {
  width: 100%;
  padding: 6px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  border: 1px solid color-mix(in srgb, var(--mc-primary) 20%, var(--mc-border-subtle));
  border-radius: var(--mc-radius-md);
  background: color-mix(in srgb, var(--mc-primary-soft) 28%, transparent);
}

.messageActions[data-message-action-surface="worker_created_first_work_handoff"] button {
  width: 100%;
  min-width: 0;
}

.messageActions[data-message-action-surface="worker_created_first_work_handoff"] button:first-of-type {
  grid-column: 1 / -1;
  border-color: color-mix(in srgb, var(--mc-primary) 42%, var(--mc-border));
  background: var(--mc-primary);
  color: var(--mc-text-inverse);
}

@media (max-width: 520px) {
  .messageActions[data-message-action-surface="mail_assistant_workqueue_handoff"] {
    grid-template-columns: 1fr;
  }

  .mailAssistantWorkQueueRunway {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .messageWorkerCreateFirstWork ol,
  .messageWorkerCreateAfterPath {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .messageActions[data-message-action-surface="worker_created_first_work_handoff"] {
    grid-template-columns: 1fr;
  }
