.composer {
  position: relative;
  z-index: 2;
  width: min(780px, calc(100% - 24px));
  max-width: 100%;
  margin: 0 auto max(14px, env(safe-area-inset-bottom));
  flex: 0 0 auto;
  align-self: end;
  justify-self: center;
  border: 1px solid color-mix(in srgb, var(--mc-border) 86%, transparent);
  border-radius: 20px;
  background:
    linear-gradient(180deg, var(--mc-surface-elevated), var(--mc-surface));
  overflow: hidden;
  box-shadow: var(--mc-elev-2);
  transition:
    border-color var(--mc-dur-fast) var(--mc-ease-out),
    box-shadow var(--mc-dur-fast) var(--mc-ease-out),
    background var(--mc-dur-fast) var(--mc-ease-out);
}

.composer:focus-within {
  border-color: color-mix(in srgb, var(--mc-primary) 46%, var(--mc-border));
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--mc-primary) 10%, transparent),
    var(--mc-elev-1);
}

.composer:has(.approvalModeMenu[open]),
.composer:has(.composerMoreMenu[open]) {
  overflow: visible;
}

.attachmentStrip {
  display: flex;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--mc-border);
  overflow-x: auto;
  overscroll-behavior-inline: contain;
}

.attachmentChip {
  min-width: 178px;
  max-width: 240px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2px 8px;
  padding: 8px 9px;
  border: 1px solid var(--mc-border-subtle);
  border-radius: 16px;
  background: color-mix(in srgb, var(--mc-surface-muted) 72%, transparent);
}

.attachmentChip span,
.attachmentChip small {
  color: var(--mc-text-subtle);
  font-size: 11px;
  line-height: 1.25;
}

.attachmentChip strong {
  grid-column: 1;
  overflow: hidden;
  color: var(--mc-text-strong);
  font-size: 12px;
  font-weight: var(--mc-weight-semibold);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.attachmentChip button {
  grid-column: 2;
  grid-row: 1 / span 3;
  width: 24px;
  height: 24px;
  align-self: center;
  border: 1px solid var(--mc-border-subtle);
  border-radius: var(--mc-radius-md);
  color: var(--mc-text-subtle);
  font-size: 14px;
  line-height: 1;
}

.attachmentChip button:hover {
  border-color: var(--mc-danger);
  background: var(--mc-danger-bg);
