@media (prefers-reduced-motion: reduce) {
  /* 진입/장식 모션(메시지·패널·직원 행 슬라이드인)은 reduced-motion 에서 끕니다. */
  .messageList .thinkingMessage,
  .messageList li,
  .teammateRow,
  .workspacePanel {
    animation: none;
  }

  /* 진행 중/작동 중 표시는 멈춰 보이면 "앱이 멈춘 것"처럼 느껴지므로, reduced-motion
     에서도 끄지 않고 위치 이동 없는 부드러운 투명도 점멸로 작동 중을 계속 알립니다. */
  .thinkingTyping [data-typing-dot],
  .thinkingDots i,
  .progressList li[data-state="running"] svg,
  .parallelRunStrip i,
  .officeSignalStrip button[data-state="running"] i,
  .officeRoundtripRail button[data-state="running"] i,
  .officeRoundtripStatus li[data-state="running"] i,
  .workerOperatingRail li[data-state="running"] > span,
  .workerStatusPanel button > span[data-running="true"]::after {
    animation: thinkingDotFade 1100ms ease-in-out infinite;
  }

  .workerCompanionMotionLane li[data-worker-companion-motion-active="true"]::after,
  .workerCompanionDeskLane button[data-worker-companion-desk-worker-active="true"] i {
    animation: none;
  }
}

