  display: grid;
  gap: 2px;
}

.aiRuntimeOnboardingCard header strong {
  color: var(--mc-text-strong);
  font-size: 14px;
  font-weight: var(--mc-weight-semibold);
}

.aiRuntimeOnboardingCard header span {
  color: var(--mc-text-muted);
  font-size: 12px;
}

.aiRuntimeOnboardingCard ol {
  margin: 0;
  padding: 0;
  list-style: none;
