/* Minimal charcoal v2 — app-wide shell and density */
.appFrame[data-design-system="minimal-charcoal-v2"] {
  /* 사용자가 핸들로 조절한 폭(--sidebar-width-user / --status-width-user)을 먼저 쓴다.
     이 값을 무시하고 뷰포트 clamp 만 쓰면 크기 조절이 화면에 반영되지 않는다. */
  --sidebar-width: var(--sidebar-width-user, clamp(238px, 22vw, 268px));
  --status-width: var(--status-width-user, clamp(250px, 23vw, 284px));
  grid-template-columns: minmax(0, 1fr) !important;
  /* 색은 테마 토큰으로 — 하드코딩하면 라이트 테마에서 이 면만 다크로 남아 섞인다. */
  background: var(--mc-bg);
}

.appFrame[data-design-system="minimal-charcoal-v2"] .canvas {
  z-index: 1;
  grid-column: 1;
}

.appFrame[data-design-system="minimal-charcoal-v2"] .sidebar,
.appFrame[data-design-system="minimal-charcoal-v2"] .statusPanel {
  position: absolute;
  z-index: 140;
  top: 8px;
  bottom: 8px;
  height: auto;
  max-height: none;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: color-mix(in srgb, var(--mc-surface) 97%, var(--mc-bg));
  box-shadow: 0 18px 56px rgba(0, 0, 0, 0.42);
  backdrop-filter: none;
