  flex-direction: column;
  align-items: flex-start;
}

.teammateRowActions .agentThreadHistory[open] { flex-basis: 100%; }

.teammateRowActions .agentThreadHistoryBody {
  width: 100%;
  margin: 2px 0 2px 6px;
}

.agentChatCreateButton,
.agentCommandCreateButton,
.agentThreadHistory > summary {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 0 5px;
  border: 1px solid transparent;
  border-radius: var(--mc-radius-sm);
  background: transparent;
  color: var(--mc-text-subtle);
  font-size: 12px;
  font-weight: var(--mc-weight-semibold);
  line-height: 1;
  cursor: pointer;
}

.agentChatCreateButton:hover,
.agentChatCreateButton:focus-visible,
.agentCommandCreateButton:hover,
.agentCommandCreateButton:focus-visible,
.agentThreadHistory > summary:hover,
.agentThreadHistory > summary:focus-visible {
